/**
 * @amc/guidance: TypeScript twin of the guidance registry and router
 * (`services/langgraph/agency/guidance`) and of the claims-audit prompt
 * compiler (`services/langgraph/agency/prompt_compiler.py`). Python is the
 * reference; `tests/fixtures/guidance-parity.json` is generated by
 * `services/langgraph/tests/test_guidance_parity_fixture.py`, and so is
 * `src/python-unicode.ts`.
 *
 * The compiler stops deliberately short of generation: its terminal success
 * state is PROMPT_PACKAGE_READY and no code path calls a provider, writes an
 * asset, publishes, sends or spends. Guidance is advisory data and never
 * redefines runtime policy, BrandCore or terminal-state semantics.
 *
 * What is passed in instead of read from disk or imported:
 * - the guidance pack files (`{name, text}`), instead of `packs/*.yaml`;
 * - the UI/UX compiler (`agency/ui_ux`, ported separately), as `UiUxCompile`.
 *
 * Deliberate differences from Python, each pinned by a fixture case:
 * - Pydantic's lax coercions are refused (numeric strings, `"yes"`/`1` for
 *   booleans, `5.0` for an int); error comparison is by `loc` and `type`.
 * - Python floats are `CanonicalFloat`; a non-integral bare number in a hashed
 *   value is refused.
 */
export * from './errors';
export * from './pyvalue';
export { loads } from './pyjson';
export { compareCodePoints, formatFixed, pyCasefold, pyLen, pyStrip, roundTo, sha256Text, sortedStrings } from './pytext';
export * from './schema';
export { PY_BOUNDARY, PY_DIGIT, PY_SPACE, ignoreCase, ignoreCaseAny, pyRegExp } from './pyre';
export * from './guidance-models';
export * from './registry';
export * from './router';
export * from './compiler-models';
export * from './claims';
export * from './compiler';
